  fail: db.prepare(`UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, worker_id = NULL, updated_at = ?
    WHERE id = ? AND status = 'running' AND worker_id = ?`),
  requeue: db.prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, worker_id = NULL, updated_at = ?
    WHERE id = ? AND status = 'running' AND worker_id = ?`),
};

const iso = () => new Date().toISOString();

function heartbeat(): void {
  try {
    stmts.beat.run(workerId, Date.now());
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}

heartbeat();
const beatTimer = setInterval(heartbeat, 500);

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  wake?.();
  setTimeout(() => process.exit(0), 3000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

async function idle(ms: number): Promise<void> {
  const ac = new AbortController();
  wake = () => ac.abort();
  try {
    await sleep(ms, undefined, { signal: ac.signal });
  } catch { /* woken */ }
  wake = null;
}

/** Processes one attempt. Returns false if the job was taken from us or we are stopping. */
async function runAttempt(job: JobRow): Promise<void> {
  const { id } = job;
  if (job.attempts <= job.fail_attempts) {
    // Transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) stmts.fail.run('transient failure', iso(), id, workerId);
    else stmts.retry.run(Date.now() + RETRY_DELAY_MS, iso(), id, workerId);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      stmts.requeue.run(iso(), id, workerId);
      return;
    }
    if (step === job.steps) {
      stmts.complete.run(job.input.toUpperCase(), iso(), id, workerId);
    } else {
      const r = stmts.progress.run(step, iso(), id, workerId);
      if (r.changes === 0) return; // job no longer ours
    }
  }
}

console.log(`worker started (${workerId})`);
while (!stopping) {
  try {
    const now = Date.now();
    stmts.pruneWorkers.run(now - 60_000);
    stmts.recover.run(iso(), workerId, now - HEARTBEAT_STALE_MS);
    const job = stmts.claim.get(workerId, iso(), now) as unknown as JobRow | undefined;
    if (job) {
      await runAttempt(job);
      continue;
    }
  } catch (e) {
    console.error('worker loop error', e);
  }
  await idle(IDLE_POLL_MS);
}

clearInterval(beatTimer);
try {
  stmts.removeWorker.run(workerId);
  db.close();
} catch { /* ignore */ }
console.log('worker stopped');
process.exit(0);

